import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    s = data[2]
    runs = []
    cur = 1
    for i in range(1, n):
        if s[i] == s[i - 1]:
            cur += 1
        else:
            runs.append(cur)
            cur = 1
    runs.append(cur)
    mism = sum(1 for i, ch in enumerate(s) if ch != 'ab'[i & 1])
    alt = min(mism, n - mism)

    def cost(L):
        if L == 1:
            return alt
        return sum(r // (L + 1) for r in runs)

    lo, hi = 1, max(runs)
    while lo < hi:
        mid = (lo + hi) // 2
        if cost(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

